package com.tekwatt.payment.service;import com.tekwatt.payment.dto.*;import com.tekwatt.payment.entity.*;import com.tekwatt.payment.repository.PaymentRepository;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class PaymentService{private final PaymentRepository repo;public PaymentService(PaymentRepository r){repo=r;}public PaymentResponse create(CreatePaymentRequest r){Optional<Payment>existing=repo.findByIdempotencyKey(r.idempotencyKey());if(existing.isPresent())return PaymentResponse.from(existing.get());Payment p=new Payment(r.tenantId(),r.userId(),r.billId(),r.invoiceId(),r.idempotencyKey(),r.provider(),r.paymentMethod(),r.amount(),r.currency());p.process();return PaymentResponse.from(repo.save(p));}@Transactional(readOnly=true)public PaymentResponse get(UUID id){return PaymentResponse.from(find(id));}@Transactional(readOnly=true)public List<PaymentResponse>list(UUID tenantId){return repo.findAllByTenantIdOrderByCreatedAtDesc(tenantId).stream().map(PaymentResponse::from).toList();}public PaymentResponse result(UUID id,PaymentResultRequest r){Payment p=find(id);if(p.getStatus()!=PaymentStatus.PROCESSING&&p.getStatus()!=PaymentStatus.PENDING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Payment is already finalized");if(r.successful()){if(r.providerReference()==null||r.providerReference().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Provider reference is required for success");p.succeed(r.providerReference());}else{p.fail(r.providerReference(),r.failureReason());}return PaymentResponse.from(p);}public PaymentResponse refund(UUID id){Payment p=find(id);if(p.getStatus()!=PaymentStatus.SUCCEEDED)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only successful payments can be refunded");p.refund();return PaymentResponse.from(p);}private Payment find(UUID id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found"));}}
